params.command:
$ErrorActionPreference='Stop'
$listenerPid=52236
$workerPid=84736
$worker=Get-CimInstance Win32_Process -Filter "ProcessId=$workerPid" -ErrorAction SilentlyContinue
if(-not $worker){ [pscustomobject]@{released=$false;reason='worker_already_gone';listenerPid=$listenerPid;workerPid=$workerPid}|ConvertTo-Json -Compress; exit 0 }
if($worker.Name -ne 'Runner.Worker.exe' -or [int]$worker.ParentProcessId -ne $listenerPid){ throw "Refusing to terminate unexpected process identity: $($worker.Name) parent=$($worker.ParentProcessId)" }
$listener=Get-CimInstance Win32_Process -Filter "ProcessId=$listenerPid" -ErrorAction SilentlyContinue
if(-not $listener -or $listener.Name -ne 'Runner.Listener.exe'){ throw 'Expected Runner.Listener.exe is not alive; refusing worker-only termination.' }
Stop-Process -Id $workerPid -Force
Start-Sleep -Seconds 3
$still=Get-Process -Id $workerPid -ErrorAction SilentlyContinue
if($still){ throw 'Runner.Worker.exe remained alive after termination.' }
[pscustomobject]@{released=$true;listenerPid=$listenerPid;workerPid=$workerPid;listenerStillAlive=[bool](Get-Process -Id $listenerPid -ErrorAction SilentlyContinue)}|ConvertTo-Json -Compress
